INSERT INTO materials (name, category, price, unit, description, image_url, in_stock, sort_order, archived) VALUES ('Кирпич силикатный красный пустотелый полуторный М-150', 'kirpich', '27 ₽', 'шт', 'Борский силикатный завод. Размер 250×120×88 мм. В упаковке (на поддоне) 336 шт — 9 072 ₽. Вес поддона 1340 кг. Красный пустотелый — для красивой кладки, лёгкий и тёплый.', '/img/brick-red-card.jpg', true, 4, false);